using System;
using Newtonsoft.Json.Linq;
using UnityEngine;
using UnityEngine.InputSystem;
using TMPro;
namespace FinalAnswer {
 public sealed class GameManager:MonoBehaviour {
  public static GameManager Instance{get;private set;}public TMP_FontAsset font;public AudioCatalog audioCatalog;
  public NetworkManager Network{get;private set;}public RoomManager Rooms{get;private set;}public PlayerManager Players{get;private set;}public RoundManager Rounds{get;private set;}public GameStateManager States{get;private set;}public MiniGameManager MiniGames{get;private set;}public SceneManager Scenes{get;private set;}public AudioManager Audio{get;private set;}public UIManager UI{get;private set;}
  public readonly SnapshotStore Snapshots=new SnapshotStore();public readonly ServerClock Clock=new ServerClock();public readonly NumberInputPreview Numbers=new NumberInputPreview();public MachineController Machine{get;private set;}
  public GameKind SelectedGame{get;private set;}=GameKind.LastCommand;public GameHall Hall{get;private set;}public readonly HostFlow HostFlow=new HostFlow();
  bool destroying;string readyKey="",clockKey="";long lastVisibility;bool visible=true;
  void Awake(){if(Instance!=null&&Instance!=this){Destroy(gameObject);return;}Instance=this;if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name!="TheLastCommand")SelectedGame=GameKind.Quiz;DontDestroyOnLoad(gameObject);Application.runInBackground=true;Application.targetFrameRate=60;
   Network=new NetworkManager();Rooms=new RoomManager(Network);Players=new PlayerManager();Rounds=new RoundManager();States=new GameStateManager();MiniGames=new MiniGameManager();Scenes=new SceneManager();Audio=gameObject.AddComponent<AudioManager>();Audio.Initialize(audioCatalog);UI=new UIManager(this,font);gameObject.AddComponent<StandaloneProbe>();if(ManualQa.Requested)gameObject.AddComponent<ManualQa>();
   Network.Message+=Receive;Network.StatusChanged+=s=>{UI.SetConnection(s);if(!Network.Authenticated){Numbers.Cancel();HostFlow.Retry();readyKey=clockKey="";}};Rooms.CredentialsReceived+=s=>{Snapshots.Clear();readyKey=clockKey="";Apply(s,"");};UnityEngine.SceneManagement.SceneManager.sceneLoaded+=SceneLoaded;
  }
  async void Start(){if(Instance!=this)return;string scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().name;if(scene=="Bootstrap"){SelectedGame=GameKind.Quiz;await Scenes.LoadGame("GameHall");}else BindMachine();}
  void SceneLoaded(UnityEngine.SceneManagement.Scene s,UnityEngine.SceneManagement.LoadSceneMode m)=>BindMachine();
  void BindMachine(){Hall=FindAnyObjectByType<GameHall>();if(Hall){MiniGames.Clear();Hall.Initialize(this);Hall.Apply(Snapshots.Current,HostFlow.Resolve(Snapshots.Current,SelectedGame));}UI.SetGame(HostFlow.Resolve(Snapshots.Current,SelectedGame));Machine=FindAnyObjectByType<MachineController>();if(!Machine)return;Machine.Initialize(this);MiniGames.Register(Machine);MiniGames.Activate(Machine.Id);if(Snapshots.Current!=null)MiniGames.Apply(Snapshots.Current);UI.SetMachine(Machine);}
  void Receive(JObject e){var p=e.Obj("payload");string type=e.S("type");if(type=="ERROR"||type.EndsWith("_REJECTED")){Numbers.Cancel();HostFlow.Retry();UI.Notify(p.S("code","Ошибка сети"));if(Network.Authenticated&&p.S("code")!="RATE_LIMITED")Network.Send("SYNC");return;}if(type=="LOCAL_DISCONNECTED"){States.Set(AppState.Disconnected);Numbers.Cancel();Audio.StopTransient();Machine?.CancelInput();return;}if(type=="ROOM_CLOSED"){Snapshots.Clear();Numbers.Cancel();Machine?.SetOffline();Audio.StopTransient();Hall?.Apply(null,SelectedGame);UI.Refresh(null);States.Set(AppState.Disconnected);return;}if(p?["revision"]!=null)Apply(p,e.S("requestId"));}
  void Apply(JObject p,string reply){if(Snapshots.Current!=null&&p.S("roomId")==Snapshots.Current.S("roomId")&&p.L("revision")<Snapshots.Current.L("revision"))return;Numbers.Snapshot(p.Obj("lastCommand"),reply);if(!Snapshots.Apply(p))return;Clock.Observe(p);Players.Apply(p);Rounds.Apply(p.Obj("lastCommand"));States.Observe(p);MiniGames.Apply(p);Hall?.Apply(p,HostFlow.Resolve(p,SelectedGame));UI.SetGame(HostFlow.Resolve(p,SelectedGame));UI.Refresh(p);}
  public string Action(string element,string action,string value=""){var panel=Snapshots.Current.Obj("lastCommand");if(panel==null||!Network.Authenticated)return "";var r=panel.Obj("testRound");var payload=new JObject{{"roomCode",Rooms.Code},{"sessionId",panel.S("sessionId")},{"element",element},{"action",action},{"value",value}};if(r.B("expanded"))payload["taskId"]=r.S("taskId");string id=Network.Send("LAST_COMMAND_ACTION",payload);if(action=="KEY"&&id!="")Numbers.Queue(id,value);return id;}
  void Update(){if(Instance!=this)return;Network.Tick();Audio.Tick();UI.Tick();RouteScene();Hall?.Tick(Clock.Now);if(Machine!=null){Machine.Tick(Clock.Now);var panel=Snapshots.Current.Obj("lastCommand");var r=panel.Obj("testRound");if(Network.Authenticated&&r.B("expanded")&&Machine.Ready){string key=panel.S("sessionId")+":"+r.S("taskId");if((r.B("awaitingReady")||r.B("waitingForTerminals"))&&key!=readyKey){readyKey=key;Action("TOUCH_PANEL","CLIENT_READY");}string challenge=panel.S("clockChallenge");if(challenge!=""&&challenge!=clockKey){clockKey=challenge;Action("TOUCH_PANEL","CLOCK_SYNC",challenge);}}}
   if(Network.Authenticated)HostFlow.Tick(Snapshots.Current,Clock.Now,Hall&&Hall.Ready,(type,payload)=>Network.Send(type,payload));
   if(Keyboard.current!=null&&!UI.Typing){if(Keyboard.current.escapeKey.wasPressedThisFrame)Machine?.CameraRig?.Overview();if(Keyboard.current.tabKey.wasPressedThisFrame)Machine?.FocusNext(Keyboard.current.shiftKey.isPressed?-1:1);if(Keyboard.current.fKey.wasPressedThisFrame)Machine?.FocusCurrent();}
  }
  void OnApplicationFocus(bool focus){visible=focus;if(Network==null)return;Machine?.CancelInput();if(Snapshots.Current.Obj("lastCommand").Obj("testRound").B("expanded")&&Network.Authenticated&&Json.MonoMs-lastVisibility>100){lastVisibility=Json.MonoMs;Action("TOUCH_PANEL","VISIBILITY",focus?"VISIBLE":"HIDDEN");if(focus)Network.Send("SYNC");}}
  void RouteScene(){string desired=HostFlow.Scene(HostFlow.Resolve(Snapshots.Current,SelectedGame));if(!Scenes.Loading&&UnityEngine.SceneManagement.SceneManager.GetActiveScene().name!=desired)_=Scenes.LoadGame(desired);}
  public void SelectGame(GameKind kind){var state=Snapshots.Current;if(state.Obj("lastCommand")!=null||state.Obj("cursedBoxes")!=null||state.Obj("impostor")!=null||state.S("gameId")!=""){UI.Notify("Сначала завершите текущую игру.");return;}SelectedGame=kind;Hall?.Apply(state,kind);UI.SetGame(kind);}
  public void StartSelectedGame(){var state=Snapshots.Current;if(state==null||!Rooms.IsHost||!Network.Authenticated){UI.Notify("Создайте комнату и дождитесь подключения телефонов.");return;}if(state.Obj("lastCommand")!=null){Action("CODE_PANEL","START_GAME");return;}if(SelectedGame==GameKind.LastCommand){Rooms.StartLastCommand(state);return;}string command=SelectedGame==GameKind.Quiz?"START_GAME":SelectedGame==GameKind.CursedBoxes?"START_CURSED_BOXES":"START_IMPOSTOR";var payload=new JObject{{"roomCode",Rooms.Code}};if(SelectedGame!=GameKind.Quiz)payload["sessionId"]=state.Obj("impostor")?.S("sessionId")??state.S("lobbyId");if(SelectedGame==GameKind.Impostor&&state.Obj("impostor")==null&&Players.Players.Count>4){UI.ChooseImpostorParticipants(ids=>{if(Rooms.Code!=payload.S("roomCode")||Snapshots.Current.S("lobbyId")!=payload.S("sessionId"))return;payload["participantIds"]=new JArray(ids);Network.Send(command,payload);});return;}if(SelectedGame==GameKind.Impostor&&state.Obj("impostor")==null)payload["participantIds"]=new JArray(System.Linq.Enumerable.Select(Players.Players,p=>p.Id));Network.Send(command,payload);}
  public void SendSession(string type,string panel){var p=Snapshots.Current.Obj(panel);if(p!=null&&Rooms.IsHost&&Network.Authenticated)Network.Send(type,new JObject{{"roomCode",Rooms.Code},{"sessionId",p.S("sessionId")}});}
  public void LeaveRoom(){Rooms.Leave();Snapshots.Clear();Numbers.Cancel();HostFlow.Retry();Machine?.SetOffline();Hall?.Apply(null,SelectedGame);UI.Refresh(null);}
  public void StartGame(){var p=Snapshots.Current.Obj("lastCommand");if(p!=null)Action("CODE_PANEL","START_GAME");else if(Snapshots.Current!=null)Rooms.StartLastCommand(Snapshots.Current);}
  public void SetNotice(string text)=>UI?.Notify(text);
  public void SaveResult(JObject r){if(r==null||r.S("status")!="WON")return;try{var path=System.IO.Path.Combine(Application.persistentDataPath,"results.json");var list=System.IO.File.Exists(path)?JArray.Parse(System.IO.File.ReadAllText(path)):new JArray();string key=Snapshots.Current.S("roomId")+":"+Snapshots.Current.Obj("lastCommand").S("sessionId")+":"+r.S("attemptId");foreach(var x in list)if(x.S("id")==key)return;list.Add(new JObject{{"id",key},{"winner",r.S("winner")},{"finishedAt",r.L("finishedAt")},{"scores",r["scores"]?.DeepClone()}});string tmp=path+".tmp";System.IO.File.WriteAllText(tmp,list.ToString());if(System.IO.File.Exists(path))System.IO.File.Replace(tmp,path,path+".bak");else System.IO.File.Move(tmp,path);}catch(Exception e){UI.Notify("Не удалось сохранить результат: "+e.GetType().Name);}}
  void OnDestroy(){if(Instance!=this||destroying)return;destroying=true;UnityEngine.SceneManagement.SceneManager.sceneLoaded-=SceneLoaded;MiniGames.Clear();Network.Dispose();UI.Dispose();Instance=null;}
 }
}
